BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
P=[['拉丁语 patere → patens，词干 patent-','敞开 → 敞开着的'],['古法语 patent(e)；lettre(s) patente(s)','公开的；授予权利的公开文书'],['中古英语 patent → 现代英语 patent','公开、明显；文书名称后来用于专利']]
W=[
E('patent','名词、动词英 /ˈpætnt/ 或 /ˈpeɪtnt/，美 /ˈpætnt/；形容词英 /ˈpeɪtnt/，美亦 /ˈpætnt/','专利；取得专利；明显的','从公开授予权利的文件，走到保护发明的专利。','拉丁 patere“敞开”的分词 patens/patent- 经法语进入英语。名词由 letters patent“公开文书”缩略而来；后来转作动词。形容词“明显的”也沿“公开可见”发展。',P,'古时 letters patent 是可以公开展示的授权文书，名字里的“开”与封闭的私人信件相对。今天 a patent 通常是发明专利：在保护范围内限制他人未经许可实施相关发明。a patent lie 则只是“明摆着的谎话”，与发明无关。','apply for a patent；hold a patent；patent an invention；a patent lie。','patent 是专利，patient 才是病人或有耐心的。专利并不等于产品的安全证明，也不自动等于在任何地方都能销售的许可。',('The company holds a patent on the valve design.','这家公司持有该阀门设计的专利。'),('His claim that nobody had warned him was a patent lie.','他说从未有人提醒过他，这显然是谎话。'),('She patented the new locking mechanism.','她为这个新的锁定机构取得了专利。'),sources=['https://www.etymonline.com/word/patent','https://www.oxfordlearnersdictionaries.com/definition/english/patent_1','https://www.oxfordlearnersdictionaries.com/definition/english/patent_2','https://www.wipo.int/en/web/patents/faq_patents']),
E('patently','英 /ˈpeɪtntli/ 或 /ˈpætntli/；美 /ˈpætntli/','显然；明摆着地','把判断说得很明白：证据已经摆在眼前。','英语 patent“明显的” + -ly。接的是形容词的公开可见义，不是名词“专利”的法律义；-ly 使它修饰另一项判断。',P+[['英语 patent + -ly → patently','明显地、无疑地']],'patently false 往往带有驳斥语气：“这明明就是假的。”它比普通 clearly 常更强调说话人认为无需再争，正式评论、辩论和书面论证中很常见。','patently false；patently absurd；patently obvious；patently unfair。','patiently 是“耐心地”，多了一个 i，来源也不同。patently 不表示“以专利方式”。',('The figures made the claim patently false.','这些数字表明，那项说法显然是错的。'),('It was patently unfair to blame the entire team for one person’s mistake.','因一个人的错误而责怪整个团队，显然不公平。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/patently','https://en.wiktionary.org/wiki/patently']),
E('patented','英 /ˈpeɪtəntɪd/','获得专利保护的；已取得专利的','某项发明已经获得专利，而不只是提出了申请。','英语 patent 的动词义“取得专利” + -ed，成为过去分词或描述状态的形容词。它接专利支线，不接 patent“明显的”支线。',P+[['英语名词 patent → 动词 patent','为发明取得专利'],['英语 patent + -ed → patented','已获专利保护的']],'a patented mechanism 强调这个机构所涉及的技术有专利保护。读广告时要把“有专利”与“效果最好”分开：前者说明权利状态，不能单凭这个词推出后者。','patented technology；a patented process；a patented design。','patent pending 是专利申请中，patented 表示已获专利；二者不是同一个阶段。patented 也不是“所有相关技术都归某家公司”的无限范围声明。',('The brochure describes a patented water-saving mechanism.','宣传册介绍了一种获得专利保护的节水机构。'),('The manufacturer licensed the patented process from a university.','制造商从一所大学取得了使用该专利工艺的许可。'),sources=['https://www.collinsdictionary.com/dictionary/english/patented','https://www.etymonline.com/word/patent','https://www.wipo.int/en/web/patents/faq_patents']),
E('patella','英、美 /pəˈtelə/','髌骨；膝盖骨','膝关节前面那块小而扁的骨头。','直接借拉丁 patella“小盘子；髌骨”，是 patina“浅盘”的小称。按形状给骨头取名；并不是 patent“公开”换了后缀。盘名与 patere 的更早关系有不同分析。',[['拉丁语 patina → patella','浅盘 → 小盘子，也用于髌骨'],['17 世纪英语 patella','借用拉丁名称，指膝盖前方的髌骨']],'把膝盖前面那块骨头想成盖在关节前的小盘子，就能看懂这个名称。日常英语通常说 kneecap；patella 多见于解剖图、运动损伤报道和医疗说明。','the left patella；a patella fracture；the position of the patella。','patella 是骨头，knee 是整个膝部或膝关节。复数可写 patellae，也可写 patellas；不要把词尾 -ella 当成英语里随处能加的“骨头”后缀。',('The diagram labels the patella at the front of the knee.','图中把膝盖前方的髌骨标了出来。'),('The report describes a small fracture of the left patella.','报告描述了左侧髌骨的一处小骨折。'),sources=['https://www.etymonline.com/word/patella','https://www.etymonline.com/word/pan','https://www.oxfordlearnersdictionaries.com/definition/english/patella'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family']for r in m['roots']if r['id']=='C0969')
excluded={w:'按用户范围暂略：罕见器皿名、礼仪名或专门解剖形态术语。'for w in ['paten','patera','patefaction','patelliform','patin']}
excluded.update(patellar='按用户范围暂略：专门髌骨相关形容词，基础认识先保留 patella。',patency='按用户范围暂略：管腔通畅度等专门医学用语。',impatent='按用户范围暂略：罕用形容词，不能与常用 impatient 混淆。')
ROOT=[dict(id='C0969',meaning='敞开、公开；另看盘形旁支',core='pat- 的核心画面是敞开着，让人能看见。',image='把折起封住的信打开，内容就能公开展示。',intro='拉丁 patere 是敞开，patens/patent- 是敞开着的。公开授予权利的文书叫 letters patent，名词缩成 patent 后逐步发展出专利义；“明摆着的”则留在形容词 patent 和副词 patently 中。',forms='patent- 是拉丁分词词干，并非英语 pat + ent。patented 是现代英语分词，patently 是形容词派生。patella 另借拉丁小盘子之名，属于需要单独说明的形状旁支。',branches=[['公开文书 → 专利','patent、patented'],['公开可见 → 明显','patent、patently'],['盘子的形状旁支','patella：小盘子比喻膝盖骨']],contrasts='patella 的直接来源是 patina/patella 盘名，不能画成 patere → patent → patella；盘名的更远来源本身有不同分析。patient、patience 属“承受”那一族，不属于这里的“敞开”。',practice='用自己的话解释 patent 的“专利”和“明显”怎样都联系公开，再用小盘子的形状记 patella。',words=[w for w in family if w not in excluded],exclude=excluded,sources=['https://www.etymonline.com/word/patent','https://www.etymonline.com/word/patella','https://www.etymonline.com/word/pan'])]
assert {w['word']for w in W}==set(family)-set(excluded)
assert all(w['word']in m['owned_words']for w in W)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history']),w['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_114_pat.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0969',len(W),'new',sum(len(w['examples'])for w in W),'examples')
